  var GEO_MAP_FRANCE = "<img src=\"data:image/jpeg;base64,\" alt=\"Carte de France à compléter\" loading=\"lazy\" decoding=\"async\">";
  var GEO_MAP_CONTINENTS = "<img src=\"data:image/png;base64,.\" alt=\"Carte des continents du monde\" loading=\"lazy\" decoding=\"async\">";
